const slots = {
  totalBudget: 1300,
  unavoidableFixedCost: 220,
  unitCost: 45,
  benefitPerUnit: 14,
  addOnCost: 130,
  addOnBenefit: 100,
  minUnitsRequired: 11
};

const answer = slots.totalBudget - slots.unavoidableFixedCost;

if (answer >= slots.minUnitsRequired * slots.unitCost) {
  const unitsWithoutAddOn = Math.floor((slots.totalBudget - slots.unavoidableFixedCost) / slots.unitCost);
  const benefitWithoutAddOn = unitsWithoutAddOn * slots.benefitPerUnit;
  return { answer: benefitWithoutAddOn };
} else {
  const unitsWithAddOn = Math.floor((slots.totalBudget - slots.unavoidableFixedCost - slots.addOnCost) / slots.unitCost);
  const benefitWithAddOn = unitsWithAddOn * slots.benefitPerUnit + slots.addOnBenefit;
  return { answer: benefitWithAddOn };
}
```

