const times = [14, 17, 16], capacities = [86, 76, 45];
const requiredFlow = 41;
const maxRouteTime = 36;

// Subproblem 1: Calculate the flow capacity of each route
const routeCapacities = times.map((time, index) => {
  const linkCapacity = capacities[index];
  return Math.min(time, linkCapacity);
});

// Subproblem 2: Check if a route meets the required flow and time constraints
function isRouteFeasible(routeCapacities, requiredFlow, maxRouteTime) {
  let totalFlow = 0;
  for (const capacity of routeCapacities) {
    totalFlow += capacity;
    if (totalFlow > requiredFlow || totalFlow + times[index] > maxRouteTime) {
      return false;
    }
  }
  return true;
}

// Subproblem 3: Find the feasible and fastest route
function findFeasibleFastestRoute(times, capacities, requiredFlow, maxRouteTime) {
  let bestRoute = null;
  for (let i = 0; i < times.length; i++) {
    const routeCapacities = times.map((time, index) => {
      const linkCapacity = capacities[index];
      return Math.min(time, linkCapacity);
    });
    if (isRouteFeasible(routeCapacities, requiredFlow, maxRouteTime)) {
      if (!bestRoute || totalFlow < bestRoute.totalFlow) {
        bestRoute = { route: i + 1, totalFlow };
      }
    }
  }
  return bestRoute;
}

// Subproblem 4: Calculate the time for each route
function calculateRouteTimes(times, capacities) {
  const routeTimes = times.map((time, index) => {
    const linkCapacity = capacities[index];
    return Math.min(time, linkCapacity);
  });
  return routeTimes;
}

// Subproblem 5: Find the fastest route based on time
function findFastestRoute(routeTimes) {
  let fastestRoute = null;
  for (let i = 0; i < routeTimes.length; i++) {
    if (!fastestRoute || routeTimes[i] < fastestRoute.time) {
      fastestRoute = { route: i + 1, time: routeTimes[i] };
    }
  }
  return fastestRoute;
}

// Subproblem 6: Calculate the total flow for each route
function calculateTotalFlow(routeCapacities) {
  let totalFlow = 0;
  for (const capacity of routeCapacities) {
    totalFlow += capacity;
  }
  return totalFlow;
}

// Subproblem 7: Find the feasible and fastest route based on both flow and time
function findFeasibleFastestRouteBasedOnBoth(times, capacities, requiredFlow, maxRouteTime) {
  let bestRoute = null;
  for (let i = 0; i < times.length; i++) {
    const routeCapacities = times.map((time, index) => {
      const linkCapacity = capacities[index];
      return Math.min(time, linkCapacity);
    });
    if (isRouteFeasible(routeCapacities, requiredFlow, maxRouteTime)) {
      const totalFlow = calculateTotalFlow(routeCapacities);
      if (!bestRoute || totalFlow < bestRoute.totalFlow) {
        bestRoute = { route: i + 1, totalFlow };
      }
    }
  }
  return bestRoute;
}

// Main program
const bestRoute = findFeasibleFastestRouteBasedOnBoth(times, capacities, requiredFlow, maxRouteTime);
console.log(`Best route: ${bestRoute.route}`);
console.log(`Total flow: ${bestRoute.totalFlow}`);
console.log(`Time: ${calculateRouteTimes(times, capacities)[bestRoute.route - 1]}`);
