const slots = {
    totalGloves: 14,
    usedPairs: 0,
    remainingGloves: 0
};

function findCompletePairs() {
    let glovesUsed = 0;
    while (glovesUsed < slots.totalGloves) {
        if (slots.remainingGloves >= 2) {
            slots.usedPairs++;
            slots.remainingGloves -= 2;
        } else {
            break;
        }
        glovesUsed += 2;
    }

    const answer = {
        completePairs: slots.usedPairs,
        remainingGloves: slots.remainingGloves
    };

    return answer;
}
