const B = { thermalComfort: 4, usefulLight: 4, energyConsumption: 4 };
const C = { thermalComfort: 3, usefulLight: 3, energyConsumption: 2 };
const D = { thermalComfort: 2, usefulLight: 5, energyConsumption: 5 };

// Define the criteria
const criteria = ['thermalComfort', 'usefulLight', 'energyConsumption'];

// Function to check if option A is dominated by option B
function isDominated(A, B) {
  for (let i = 0; i < criteria.length; i++) {
    if (A[criteria[i]] >= B[criteria[i]]) continue;
    return true;
  }
  return false;
}

// Eliminate dominated options
const frontier = [A, B, C, D];
frontier = frontier.filter(option => !frontier.some(otherOption => isDominated(option, otherOption)));

// Check if the remaining frontier has a unique winner
if (frontier.length === 1) {
  console.log(frontier[0]);
} else {
  console.log("No unique winner");
}
```

