const slots = {
  bendingAngle: [20, 21, 20, 19, 21, 30]
};

const facts = {};

const intermediate1 = slots.bendingAngle;
const intermediate2 = intermediate1.map((value) => value - intermediate1[0]);

const answer = intermediate2.reduce((acc, curr) => {
  if (Math.abs(curr) > 5) {
    return acc + 1;
  }
  return acc;
}, 0);

if (answer === 0) {
  console.log("No isolated suspicious point.");
} else if (answer === intermediate2.length - 1) {
  console.log("Gradual drift.");
} else {
  console.log("Isolated suspicious point.");
}

const center = intermediate2.reduce((acc, curr, index) => {
  if (index % 2 === 0) {
    return acc + curr;
  }
  return acc;
}, 0) / intermediate2.length;

console.log(`Robust estimate of the center of the series: ${center}`);
```

