  "intermediate": [
    {
      "$name": "distance_estimation",
      "jsEval": `
        const map = slots.map;
        const elevation_change = slots.map.elevation_change;
        const resources = slots.resources;
        const weather = slots.weather;

        // Calculate distance based on map scale and elevation change
        const real_distance = map.distance * (1 + elevation_change / 100);

        return {
          distance: real_distance,
          water: resources.water,
          energy: resources.energy
        };
      `
    },
    {
      "$name": "resources_calculated",
      "jsEval": `
        const distance_estimation = slots.distance_estimation;
        const weather = slots.weather;

        // Calculate resources based on weather speed and real distance
        const water_needed = 0.5 * distance_estimation.distance / weather.speed;
        const energy_needed = 0.3 * distance_estimation.distance / weather.speed;

        return {
          water: Math.min(water_needed, resources.water),
          energy: Math.min(energy_needed, resources.energy)
        };
      `
    }
  ],
  "answer": {
    "$name": "final_resources",
    "jsEval": `
      const resources_calculated = slots.resources_calculated;
      return resources_calculated;
    `
  }
}
