const slots = {
  A: { units: 10, needScore: 5 },
  B: { units: 20, needScore: 4 },
  C: { units: 30, needScore: 7 }
};

const facts = {};

const equalAllocation = (slots) => {
  const totalUnits = Object.values(slots).reduce((acc, slot) => acc + slot.units, 0);
  const equalShare = totalUnits / slots.length;
  return { A: equalShare, B: equalShare, C: equalShare };
};

const needProportionalAllocation = (slots) => {
  const totalNeedScore = Object.values(slots).reduce((acc, slot) => acc + slot.needScore, 0);
  const needShare = totalNeedScore / slots.length;
  return { A: needShare, B: needShare, C: needShare };
};

const answer = (slots, facts) => {
  const equalResult = equalAllocation(slots);
  const needProportionalResult = needProportionalAllocation(slots);

  if (equalResult.A > needProportionalResult.A) {
    return "Equal allocation gives more to the highest-need district.";
  } else if (equalResult.A < needProportionalResult.A) {
    return "Need-proportional allocation gives more to the highest-need district.";
  } else {
    return "Both allocations give equal amount to the highest-need district.";
  }
};

const result = answer(slots, facts);
```

