@slots budget = 15;
@facts tree_planting = (5,7); bridge_repair = (6,9); library_books = (3,4); drainage = (5,8);
@answer maxBenefitPlan;

@slots mandatoryProjects = [tree_planting, bridge_repair];
@slots remainingBudget = budget - mandatoryProjects.reduce((acc, project) => acc + project[0], 0);

function calculateBenefit(plan) {
    return plan.reduce((acc, project) => acc + project[1], 0);
}

function isFeasible(plan) {
    const totalCost = plan.reduce((acc, project) => acc + project[0], 0);
    return totalCost <= remainingBudget;
}

@slots feasiblePlans = [];
for (let i = 0; i < mandatoryProjects.length; i++) {
    for (let j = i + 1; j <= mandatoryProjects.length; j++) {
        const subset = mandatoryProjects.slice(i, j);
        if (isFeasible(subset)) {
            feasiblePlans.push(subset);
        }
    }
}

@slots bestPlan = null;
for (const plan of feasiblePlans) {
    const benefit = calculateBenefit(plan);
    if (!bestPlan || benefit > maxBenefitPlan) {
        maxBenefitPlan = benefit;
        bestPlan = plan;
    }
}

@answer maxBenefitPlan
```

